db.createCollection("posts", {
   validator: {
      $jsonSchema: {
         bsonType: "object",
         required: [ "title", "content", "authorId" ],
         properties: {
            title: {
               bsonType: "string",
               description: "must be a string and is required"
            },
            authorId: {
               bsonType: "objectId",
               description: "must be an objectid and is required"
            },
            tags: {
               bsonType: [ "array" ],
               items: {
                  bsonType: "string"
               }
            }
         }
      }
   }
});
